import { expect, test } from "@jest/globals";
import * as z from "../index";
for (const asynchronous of [false, true]) {
  test(`record own presence ${asynchronous}`, async () => {
    const input = Object.assign(Object.create({ inherited: "omit" }), { present: undefined });
    const schema = z.record(z.any());
    const output = asynchronous ? await schema.parseAsync(input) : schema.parse(input);
    expect(Object.prototype.hasOwnProperty.call(output, "present")).toBe(true);
    expect(Object.prototype.hasOwnProperty.call(output, "inherited")).toBe(false);
    expect(Object.keys(output)).toEqual(["present"]);
  });
  test(`record transformed presence ${asynchronous}`, async () => {
    const schema = z.record(z.string().transform(() => undefined));
    const output = asynchronous ? await schema.parseAsync({ present: "input" }) : schema.parse({ present: "input" });
    expect(Object.prototype.hasOwnProperty.call(output, "present")).toBe(true);
    expect(output.present).toBeUndefined();
  });
}
